head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
// jackal_11.05.12

scwin.vScrenID = "ULDSTF70021.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EN; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lcd.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // jackal_11.05.12 상장종목 여부 체크 추가

scwin.fn_search = function() {
    var url = "/digital/Lstproc.do?method=searchDigitalAdministrativeIssue";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&DIV_IDX=" + 11 + "&ISUR_CD=" + txb_ISUR_CD.getValue();

    //alert(url);
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts.getCellData(dts.getRowPosition(), "ADMISU_DESIGN_BZ_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[8] = dts.getCellData(dts.getRowPosition(), "ADMISU_DESIGN_BZ_PROCS_NO"); // 지정업무처리번호

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션

    if ($c.stf.getObjectValue(txb_ISUR_CD).length == 0) {
        arrPar[0] = ""; // 발행기관코드값
        arrPar[1] = ""; // 발행기관명
        arrPar[6] = ""; // 종목코드값
        arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else {
        arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 발행기관코드값
        arrPar[1] = $c.stf.getObjectValue(txb_ISUR_NM); // 발행기관명
        arrPar[6] = ""; // 종목코드값
        arrPar[7] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = 0; // 지정및해제구분코드
    arrPar[8] = ""; // 지정업무처리번호

};


// 상장신청인 선택 팝업호출용
scwin.fn_GetParIsur2 = function(arrPar) {
    arrPar[0] = "";
    arrPar[1] = "";
    arrPar[2] = "";
    return arrPar.length;
};


// 상장신청인 선택 팝업호출용
scwin.fn_SetParIsur2 = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
    scwin.vIsurCd = arrPar[0].ISUR_CD;
    scwin.fn_search();
};
scwin.fn_Reg = async function() {
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    await $c.frame.CreateDialogFrame("DLG_0", "../digital/ULDSTF70022.gfm", "신종증권 관리종목지정", 200, 50, 770, 400, "window");
};
scwin.img_Search_onclick = function() {
    scwin.fn_search();
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    //FillGridHeaderTotalCnt(rowcount, panel_page);
    txb_TotCnt.setValue("총건수 : " + rowcount);
    dts.setRowPosition(rowcount, 0);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.img_Excel_onclick = function() {
    if (dts.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, "신종증권 괸리종목(상장신청인기준)지정내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Regist_onclick = function() {
    scwin.fn_Reg();
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    scwin.vIsurCd = dts.getCellData(dts.getRowPosition(), "ISUR_CD");
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;
    await $c.frame.CreateDialogFrame("DLG_0", "../digital/ULDSTF70022.gfm", "신종증권 관리종목지정", 200, 50, 770, 400, "window");
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur2;
    scwin.fn_SetPar = fn_SetParIsur2;
    $c.lcd.fn_PopFindDigitalIsurAll();
};
scwin.txb_ISUR_CD_onchange = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD).length == 0) {
        txb_ISUR_NM.setValue("");
    }
};
